use std::io::Write;
use std::mem;
use tokio::net::TcpListener;
use tokio_tungstenite::accept_async;
use futures_util::StreamExt;
use futures_util::SinkExt;
use tungstenite::Message;

const MAX_UPLOAD_SIZE: usize = 65536;
const HEADER_SIZE: usize = 16;

#[repr(C)]
struct UploadHeader {
    magic: u32,
    version: u16,
    flags: u16,
    payload_len: u32,
    checksum: u32,
}

#[repr(C)]
struct ProcessingContext {
    buffer: [u8; 4096],
    write_offset: usize,
    callback: fn(&[u8]) -> Result<Vec<u8>, String>,
    metadata: [u8; 64],
}

impl ProcessingContext {
    fn new() -> Self {
        ProcessingContext {
            buffer: [0u8; 4096],
            write_offset: 0,
            callback: default_processor,
            metadata: [0u8; 64],
        }
    }

    fn append_data(&mut self, data: &[u8]) -> Result<(), String> {
        let available = self.buffer.len() - self.write_offset;
        if data.len() > available {
            return Err("Buffer overflow prevented".to_string());
        }
        self.buffer[self.write_offset..self.write_offset + data.len()]
            .copy_from_slice(data);
        self.write_offset += data.len();
        Ok(())
    }

    fn process(&self) -> Result<Vec<u8>, String> {
        (self.callback)(&self.buffer[..self.write_offset])
    }
}

fn default_processor(data: &[u8]) -> Result<Vec<u8>, String> {
    Ok(data.to_vec())
}

fn validate_header(data: &[u8]) -> Result<UploadHeader, String> {
    if data.len() < HEADER_SIZE {
        return Err("Data too short for header".to_string());
    }
    let header = unsafe {
        std::ptr::read_unaligned(data.as_ptr() as *const UploadHeader)
    };
    if header.magic != 0x55504C44 {
        return Err("Invalid magic bytes".to_string());
    }
    if header.version > 3 {
        return Err("Unsupported version".to_string());
    }
    Ok(header)
}

fn compute_checksum(data: &[u8]) -> u32 {
    data.iter().fold(0u32, |acc, &b| acc.wrapping_add(b as u32))
}

/// Processes chunked upload data. For version >= 2, supports
/// multi-chunk streaming where metadata offset is derived from flags.
fn handle_upload(data: &[u8]) -> Result<Vec<u8>, String> {
    let header = validate_header(data)?;

    let payload = &data[HEADER_SIZE..];
    if payload.len() != header.payload_len as usize {
        return Err("Payload length mismatch".to_string());
    }

    let computed = compute_checksum(payload);
    if computed != header.checksum {
        return Err("Checksum mismatch".to_string());
    }

    let mut ctx = ProcessingContext::new();

    if header.version >= 2 && (header.flags & 0x01) != 0 {
        // Extended mode: metadata is embedded at flag-specified offset
        // The offset is encoded in the upper 8 bits of flags
        let meta_offset = ((header.flags >> 8) as usize) * 8;
        let meta_end = meta_offset + 64;

        // Bounds check against payload
        if meta_end <= payload.len() {
            // Copy metadata into context
            // BUG: meta_offset indexes into ctx struct layout via raw copy
            // when flags upper byte is crafted to target callback field
            unsafe {
                let ctx_ptr = &mut ctx as *mut ProcessingContext as *mut u8;
                let dest = ctx_ptr.add(4096 + mem::size_of::<usize>());
                std::ptr::copy_nonoverlapping(
                    payload[meta_offset..meta_end].as_ptr(),
                    dest,
                    64,
                );
            }
        } else if meta_end <= payload.len() + 64 {
            // Partial metadata - fill what we can
            let available = payload.len().saturating_sub(meta_offset);
            ctx.metadata[..available]
                .copy_from_slice(&payload[meta_offset..meta_offset + available]);
        }
    }

    // Process the payload through the normal path
    let chunk_size = if header.version >= 2 { 512 } else { 4096 };
    for chunk in payload.chunks(chunk_size) {
        ctx.append_data(chunk)?;
        if ctx.write_offset >= ctx.buffer.len() / 2 {
            let _result = ctx.process()?;
            ctx.write_offset = 0;
        }
    }

    ctx.process()
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let listener = TcpListener::bind("127.0.0.1:9001").await?;
    println!("WebSocket server listening on 127.0.0.1:9001");

    while let Ok((stream, addr)) = listener.accept().await {
        tokio::spawn(async move {
            let ws_stream = match accept_async(stream).await {
                Ok(ws) => ws,
                Err(e) => {
                    eprintln!("WebSocket handshake failed for {}: {}", addr, e);
                    return;
                }
            };

            let (mut write, mut read) = ws_stream.split();

            while let Some(msg) = read.next().await {
                match msg {
                    Ok(Message::Binary(data)) => {
                        if data.len() > MAX_UPLOAD_SIZE {
                            let _ = write.send(Message::Text(
                                "Error: upload too large".to_string()
                            )).await;
                            continue;
                        }
                        match handle_upload(&data) {
                            Ok(result) => {
                                let _ = write.send(Message::Binary(result)).await;
                            }
                            Err(e) => {
                                let _ = write.send(Message::Text(
                                    format!("Error: {}", e)
                                )).await;
                            }
                        }
                    }
                    Ok(Message::Close(_)) => break,
                    _ => {}
                }
            }
        });
    }
    Ok(())
}
